// Block (composition) — a responsive, full-width catalog of ProductCard Blocks.
import type { Ref } from "react";
import { Grid } from "../layouts/Grid";
import type { Responsive } from "../layouts/responsive";
import { ProductCard, type ProductCardProps } from "./ProductCard";
import "./ProductGrid.css";

export interface ProductGridProps {
  products: (ProductCardProps & { id: string })[];
  columns?: Responsive<number>;
  className?: string;
  ref?: Ref<HTMLElement>;
}

export function ProductGrid({
  products,
  columns = { small: 2, medium: 4 },
  className,
  ref,
}: ProductGridProps) {
  return (
    <Grid
      as="section"
      ref={ref}
      columns={columns}
      gap="medium"
      aria-label="Products"
      className={className ? `sd-productgrid ${className}` : "sd-productgrid"}
    >
      {products.map(({ id, ...product }) => (
        <ProductCard key={id} {...product} />
      ))}
    </Grid>
  );
}

/* ProductGrid.css — .sd-productgrid (Block)
   Arrangement only: the responsive Grid owns columns and gap. */
.sd-productgrid {
  width: 100%;
}
